package evidence

import (
	"encoding/json"
	"math/rand"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// Every correctly rehashed negative fixture (generated by the Python reference)
// must be rejected with its pinned error code. Because the chain is valid, the
// rejection can only come from the semantic rule.
func TestNegativeFixturesRejectedWithPinnedCode(t *testing.T) {
	files, err := filepath.Glob(filepath.Join("..", "..", "fixtures", "contracts", "negative", "*.json"))
	if err != nil || len(files) < 20 {
		t.Fatalf("negative fixtures missing: %v (%d)", err, len(files))
	}
	for _, path := range files {
		name := filepath.Base(path)
		t.Run(name, func(t *testing.T) {
			raw, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			var f struct {
				Expect  string            `json:"expect_code"`
				Events  []json.RawMessage `json:"events"`
				Objects map[string]string `json:"objects"`
			}
			if err := json.Unmarshal(raw, &f); err != nil {
				t.Fatal(err)
			}
			var evs []Event
			for _, r := range f.Events {
				e, err := ParseEvent(r)
				if err != nil {
					t.Fatal(err)
				}
				evs = append(evs, e)
			}
			objs := map[string][]byte{}
			for h, s := range f.Objects {
				objs[h] = []byte(s)
			}
			errs := Verify(evs, objs)
			for _, e := range errs {
				if strings.Contains(e, "[CHAIN] hash mismatch") {
					t.Fatalf("fixture is not correctly rehashed: %v", errs)
				}
			}
			for _, e := range errs {
				if strings.Contains(e, "["+f.Expect+"]") {
					return
				}
			}
			t.Fatalf("expected code %s, got %v", f.Expect, errs)
		})
	}
}

func TestStructuralOnlyIsDistinctFromFullVerification(t *testing.T) {
	evs, objs := loadGolden(t, "complete-turn.json")
	if errs := VerifyStructure(evs); len(errs) != 0 {
		t.Fatalf("structure: %v", errs)
	}
	if errs := VerifyFull(evs, objs); len(errs) != 0 {
		t.Fatalf("full: %v", errs)
	}
	// Structural verification cannot see object problems; full verification can.
	empty := map[string][]byte{}
	if errs := VerifyFull(evs, empty); len(errs) == 0 || !strings.Contains(strings.Join(errs, ";"), "[OBJECT] missing") {
		t.Fatalf("full verification must report missing objects: %v", errs)
	}
	if errs := VerifyFull(evs, nil); len(errs) == 0 {
		t.Fatal("VerifyFull(nil) must not silently degrade to structural-only")
	}
	short := map[string][]byte{}
	for h, b := range objs {
		short[h] = b[:len(b)-1]
	}
	if errs := VerifyFull(evs, short); !strings.Contains(strings.Join(errs, ";"), "[OBJECT]") {
		t.Fatalf("digest mismatch not reported: %v", errs)
	}
	// Same digest, wrong declared length (cannot happen with SHA-256 unless the
	// declaration lies): the declared length is checked separately.
	evs2, objs2 := loadGolden(t, "complete-turn.json")
	payload(evs2[3])["objects"].([]any)[0].(map[string]any)["bytes"] = json.Number("1")
	_ = Seal(evs2[3])
	if errs := VerifyFull(rechain(t, evs2), objs2); !strings.Contains(strings.Join(errs, ";"), "[LENGTH]") {
		t.Fatalf("declared length not enforced: %v", errs)
	}
}

func TestStrictJSONRejectsAmbiguousInput(t *testing.T) {
	for name, raw := range map[string]string{
		"duplicate key":        `{"a":1,"a":2}`,
		"nested duplicate key": `{"a":{"b":1,"b":2}}`,
		"trailing data":        `{"a":1} {"b":2}`,
		"trailing garbage":     `{"a":1} x`,
		"truncated":            `{"a":`,
		"invalid utf8":         "{\"a\":\"\xff\"}",
		"lone surrogate":       `{"a":"\ud800"}`,
		"too deep":             strings.Repeat("[", 200) + strings.Repeat("]", 200),
		"empty":                ``,
	} {
		if _, err := ParseJSON([]byte(raw)); err == nil {
			t.Errorf("%s: accepted", name)
		}
	}
	// Invalid UTF-8 is rejected, not normalized to U+FFFD (which would change the hash).
	if _, err := ParseEvent([]byte("{\"type\":\"a\xc3\x28\"}")); err == nil {
		t.Error("invalid UTF-8 normalized")
	}
	if _, err := ParseEventLog([]byte("{\"a\":1}\n{\"a\":1,\"a\":2}\n")); err == nil {
		t.Error("event log with a duplicate key accepted")
	}
	if evs, err := ParseEventLog([]byte("{\"a\":1}\n\n{\"b\":2}\n")); err != nil || len(evs) != 2 {
		t.Errorf("valid log: %v %v", evs, err)
	}
	// Unknown optional fields survive and are hashed (MINOR compatibility).
	evs, _ := loadGolden(t, "complete-turn.json")
	evs[1]["x_future_field"] = map[string]any{"k": "v"}
	_ = Seal(evs[1])
	errs := Verify(rechain(t, evs), nil)
	for _, e := range errs {
		if strings.Contains(e, "x_future_field") || strings.Contains(e, "unsupported") {
			t.Errorf("unknown optional field rejected: %v", errs)
		}
	}
}

// Malformed input yields verification errors; it never panics.
func TestVerifierNeverPanicsOnMalformedInput(t *testing.T) {
	rnd := rand.New(rand.NewSource(7))
	junk := []any{nil, 1, "x", []any{}, map[string]any{}, []any{nil}, map[string]any{"sha256": 1}, true, json.Number("1.5")}
	for i := 0; i < 400; i++ {
		evs, objs := loadGolden(t, "complete-turn.json")
		e := evs[rnd.Intn(len(evs))]
		keys := []string{"payload", "actor", "seq", "type", "prev_hash", "event_hash", "recorded_at", "schema_version", "tenant_id"}
		if rnd.Intn(2) == 0 {
			p := payload(e)
			for k := range p {
				keys = append(keys, "payload."+k)
			}
		}
		k := keys[rnd.Intn(len(keys))]
		v := junk[rnd.Intn(len(junk))]
		if rest, ok := strings.CutPrefix(k, "payload."); ok {
			payload(e)[rest] = v
		} else {
			e[k] = v
		}
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Fatalf("panic on mutation %s=%v: %v", k, v, r)
				}
			}()
			_ = Verify(evs, objs)
			_ = DeriveDisclosure(evs)
		}()
	}
	for _, evs := range [][]Event{nil, {}, {nil}, {{}}, {{"payload": 3}}} {
		_ = Verify(evs, nil)
	}
}
